272	            refuseIfUnproven(claim, settling);
273	        }
274	        if (to == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, settling)) {
275	            // above the clerk limit: a steward approves or rejects it
276	            to = ClaimStatus.PENDING;
277	        }
278	        RollupService.Snapshot before = rollup.snapshot(sheetId);
279	        // a voided claim keeps its number (never reused), and the VOIDED record carries it
280	        String number = claim.getNumber();
281	        // a voided SETTLED claim keeps its frozen figure, which leaves every total
282	        boolean reversing = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
