438	            throw new ResponseStatusException(HttpStatus.CONFLICT,
439	                    "A " + claim.getStatus() + " claim takes no more proofs");
440	        }
441	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
442	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
443	        claim.addProof();
444	        claims.flush();
445	        record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), " proofs=" + claim.getProofs());
446	        return claim;
447	    }
