524	    /** A steward (or a role the permission matrix lets reassign) moves a DRAFT, OPEN or PENDING claim to another person on the sheet: it keeps its
525	     *  number and date, is listed as the new person's newest claim, and loses any figure a
526	     *  statement bound it to (live again until the new person's next statement). Refused (404)
527	     *  when the claim or person is missing, (423) when it is dated in a closed period, (403) for a
528	     *  role the sheet's permission matrix does not let reassign, (409) when SETTLED or VOID or already the person's, and (422) when it is dated after
529	     *  the new person's retirement date. */
530	    @Transactional
531	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
532	        Claim claim = claims.findForUpdate(id, sheetId)
533	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
534	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
535	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
536	        refuseIfClosed(sheetId, claim.getDate());
537	        settings.refuseUnlessAllowed(sheetId, user, Permission.REASSIGN);
538	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
539	            throw new ResponseStatusException(HttpStatus.CONFLICT,
540	                    "A " + claim.getStatus() + " claim cannot be reassigned");
541	        }
542	        if (claim.getPersonId() == toPersonId) {
543	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already that person's");
544	        }
545	        refuseIfRetired(to, claim.getDate());
546	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
547	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
548	        RollupService.Snapshot before = rollup.snapshot(sheetId);
