559	    /** Split an amount off an OPEN claim: the claim keeps the rest of its amount and loses any
560	     *  figure a statement bound it to, and a new OPEN claim of the amount, with the same date and
561	     *  note, the next number, opened by the user, its due-by fixed now from the terms in force on
562	     *  the date (the person's own, else their grade's, else the sheet's), and naming the original's number as split-from, is listed as the person's newest.
563	     *  Refused (404) when missing, (423) when dated in a closed period, (403) for a role the
564	     *  sheet's permission matrix does not let open a claim, (409) unless OPEN and not deferred on
565	     *  the sheet's today, and (422) unless the amount is more than 0.00 and less than the claim's. */
566	    @Transactional
567	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
568	        Claim claim = claims.findForUpdate(id, sheetId)
569	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
570	        refuseIfClosed(sheetId, claim.getDate());
571	        settings.refuseUnlessAllowed(sheetId, user, Permission.OPEN);
572	        if (claim.getStatus() != ClaimStatus.OPEN) {
573	            throw new ResponseStatusException(HttpStatus.CONFLICT,
574	                    "Only an OPEN claim is split, not a " + claim.getStatus() + " one");
575	        }
576	        if (claim.isDeferredOn(sheets.today(sheetId))) {
577	            throw new ResponseStatusException(HttpStatus.CONFLICT,
578	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be split before then");
579	        }
580	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
581	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
582	                    "The amount split off must be more than 0.00 and less than the claim's");
583	        }
584	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
585	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
586	        RollupService.Snapshot before = rollup.snapshot(sheetId);
587	        LocalDate on = claim.getDate();
588	        claim.setAmount(claim.getAmount().subtract(amount));
589	        claim.unbind();
590	        int terms = person.getTerms() != null ? person.getTerms()
591	                : sheets.find(sheetId).map(s -> s.termsFor(person.gradeOn(on), on)).orElse(Sheet.DEFAULT_TERMS);
592	        Claim fresh = new Claim(sheetId, person.getId(), amount, on, on.plusDays(terms), claim.getNote());
593	        fresh.setStatus(ClaimStatus.OPEN);
594	        fresh.setNumber(nextNumber(sheetId, on));
595	        fresh.setOpenedBy(user);
596	        fresh.setSplitFrom(claim.getNumber());
597	        fresh.setListed(claims.findLastListed(sheetId) + 1);
598	        Claim split = claims.saveAndFlush(fresh);
599	        logStatus(user, person, split);
600	        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), " into=" + split.getNumber());
601	        record("CLAIM_OPENED", user, person, split);
602	        rollup.recordChanges(sheetId, user, before);
603	        return new Split(claim, split);
604	    }
