635	    /** Take a statement of a person: record their due-total now, and bind each of their claims
636	     *  that counts (OPEN, PENDING or SETTLED, but no unbound open one within a hold, nor a deferred one) to its figure now; the others
637	     *  are left unbound. Taken as of a date ({@code asOf}, not null), the sheet as it stood at the end
638	     *  of that date stands in for it now (see {@link #statementAsOf}). */
639	    @Transactional
640	    public Statement statement(String sheetId, String user, long personId, LocalDate asOf) {
641	        if (asOf != null) {
642	            return statementAsOf(sheetId, user, personId, asOf);
643	        }
644	        Person person = people.findForUpdate(personId, sheetId)
645	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
646	        LocalDate today = sheets.today(sheetId);
647	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
648	        RollupService.Snapshot before = rollup.snapshot(sheetId);
649	        List<Claim> counted = theirs.stream().filter(c -> counts(c, person, today)).toList();
650	        BigDecimal dueTotal = Sheet.capped(dueTotalOf(counted, person, today), sheets.cap(sheetId));
651	        for (Claim c : theirs) {
652	            if (counts(c, person, today)) {
653	                // the statement binds the figure; the late charge keeps following the sheet's today
654	                c.bind(c.getSettledDue() != null ? c.getSettledDue() : figureOf(c, person));
655	            } else {
656	                c.unbind();
657	            }
658	        }
659	        claims.flush();
660	        return stated(sheetId, user, person, theirs, dueTotal, counted.size(), today, null, before);
661	    }
