663	    /** Take a statement of a person as of a date on or before the sheet's today: their claims that
664	     *  counted at the end of it are bound to their figures as they stood then (every change made
665	     *  while the sheet's today was on or before it counts, every later one does not), with that date
666	     *  standing in for the sheet's today in every figure; their other claims are left unbound.
667	     *  Refused (422) when the date is after the sheet's today, or the person was not yet added then. */
668	    private Statement statementAsOf(String sheetId, String user, long personId, LocalDate asOf) {
669	        Person person = people.findForUpdate(personId, sheetId)
670	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
671	        LocalDate today = sheets.today(sheetId);
672	        if (asOf.isAfter(today)) {
673	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
674	                    "A statement is taken as of a date on or before the sheet's today");
675	        }
676	        HistoryService.AsOf then = history.asOf(sheetId, asOf);
677	        Person was = then.people().get(personId);
678	        if (was == null) {
679	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
680	                    "The person was not yet on the sheet on " + asOf);
681	        }
682	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
683	        RollupService.Snapshot before = rollup.snapshot(sheetId);
684	        RollupService.Stated stated = RollupService.statedOn(then.sheet(), was, personId,
685	                List.copyOf(then.claims().values()), then.rates());
686	        Map<Long, BigDecimal> bound = new HashMap<>();
687	        then.claims().forEach((id, c) -> {
688	            if (stated.counted().containsKey(c)) {
689	                bound.put(id, stated.counted().get(c));
690	            }
691	        });
692	        for (Claim c : theirs) {
693	            if (bound.containsKey(c.getId())) {
694	                c.bind(bound.get(c.getId()));
695	            } else {
696	                c.unbind();
697	            }
698	        }
699	        claims.flush();
700	        return stated(sheetId, user, person, theirs, stated.dueTotal(), stated.counted().size(), today, asOf, before);
701	    }
