703	    /** Record a statement just taken (as of {@code asOf}, or null) and audit it. */
704	    private Statement stated(String sheetId, String user, Person person, List<Claim> theirs, BigDecimal dueTotal,
705	            int counted, LocalDate today, LocalDate asOf, RollupService.Snapshot before) {
706	        statements.saveAndFlush(new PersonStatement(sheetId, person.getId(), dueTotal, counted, today, asOf, user));
707	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
708	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted
709	                + (asOf == null ? "" : " asof=" + asOf));
710	        rollup.recordChanges(sheetId, user, before);
711	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(person.getId())), theirs);
712	    }
