714	    /** A steward cancels a person's last statement: it is removed, and every claim it bound is
715	     *  live again (a figure an earlier statement bound is not restored). Refused (404) when the
716	     *  person is missing, (403) for anyone but a steward, and (409) when the person has no
717	     *  statement. */
718	    @Transactional
719	    public Statement cancelStatement(String sheetId, String user, long personId) {
720	        Person person = people.findForUpdate(personId, sheetId)
721	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
722	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
723	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward cancels a statement");
724	        }
725	        List<PersonStatement> taken = statements.findByPersonIdOrderByIdAsc(personId);
726	        if (taken.isEmpty()) {
727	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person has no statement to cancel");
728	        }
729	        PersonStatement last = taken.get(taken.size() - 1);
730	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
731	        RollupService.Snapshot before = rollup.snapshot(sheetId);
732	        theirs.forEach(Claim::unbind);
733	        claims.flush();
734	        statements.delete(last);
735	        statements.flush();
736	        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
737	                + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString()));
738	        rollup.recordChanges(sheetId, user, before);
739	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
740	    }
