742	    /** The number a claim dated {@code date} takes as it is opened: under period numbering (set,
743	     *  and the sheet's today on or after it) the next within the period containing the date
744	     *  (<period name>-<n>), or X-<n> when none does; otherwise the sheet's next number. */
745	    private String nextNumber(String sheetId, LocalDate date) {
746	        if (!sheets.periodNumberingOn(sheetId)) {
747	            return String.valueOf(sheets.nextClaimNumber(sheetId));
748	        }
749	        // held until the transaction ends, so two claims opened at once are numbered one after the other
750	        sheets.lock(sheetId);
751	        String prefix = periods.containing(sheetId, date).map(Period::getName).orElse(NO_PERIOD) + "-";
752	        List<String> given = new ArrayList<>(claims.findNumbers(sheetId));
753	        given.addAll(retired.findNumbers(sheetId));
754	        int last = given.stream()
755	                .filter(n -> n.startsWith(prefix))
756	                .map(n -> n.substring(prefix.length()))
757	                .filter(n -> n.matches("\\d{1,9}"))
758	                .mapToInt(Integer::parseInt)
759	                .max().orElse(0);
760	        return prefix + (last + 1);
761	    }
