800	    /** Whether a claim counts toward claimed and due totals: only OPEN (or PENDING) and SETTLED ones
801	     *  do, but not an open one dated within a hold of its person, nor one of a person whose
802	     *  retirement date the sheet's today has reached, unless bound by a statement, nor one deferred
803	     *  on the sheet's today. */
804	    private static boolean counts(Claim c, Person person, LocalDate today) {
805	        return c.getStatus() == ClaimStatus.SETTLED
806	                || (c.getStatus().isOpen() && !c.isDeferredOn(today)
807	                        && (c.isBound() || !(person.heldOn(c.getDate()) || person.retiredOn(today))));
808	    }
