810	    /** The due a claim shows: the due fixed when it was settled, else its figure with its late
811	     *  charge on top, raised to the floor in force on its date. */
812	    private BigDecimal shownDueOf(Claim claim, Person person) {
813	        if (claim.getSettledDue() != null) {
814	            return claim.getSettledDue();
815	        }
816	        return flooredOf(claim,
817	                LateCharge.of(sheets.find(claim.getSheetId())).addTo(claim, figureOf(claim, person), roundingOf(claim)));
818	    }
819	
820	    /** A due (null: n/a, which stays n/a) raised to the sheet's floor in force on the claim's date; a
821	     *  correction's never is. */
822	    private BigDecimal flooredOf(Claim claim, BigDecimal due) {
823	        if (due == null || claim.isCorrection()) {
824	            return due;
825	        }
826	        return due.max(sheets.floorOn(claim.getSheetId(), claim.getDate()));
827	    }
828	
829	    /** A claim's figure before any late charge or floor: the one a statement bound it to (null: n/a),
830	     *  else (unbound, or PENDING) its rate figure. */
831	    private BigDecimal figureOf(Claim claim, Person person) {
832	        return claim.isBound() ? claim.getStatedDue() : rateFigureOf(claim, person);
833	    }
834	
835	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
836	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
837	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
838	    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
839	        List<BigDecimal> dues = counted.stream().map(c -> shownDueOf(c, person)).filter(d -> d != null).toList();
840	        if (rates.findInForce(person.getSheetId(), person.gradeOn(today), today).isEmpty() && dues.isEmpty()) {
841	            return null;
842	        }
843	        return dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
844	    }
845	
846	    /** The claim's amount times the rate, in force on the claim's date, of its person's grade then, divided by
847	     *  100, rounded as its rounding policy has it; null with no rate in force then. */
848	    private BigDecimal rateFigureOf(Claim claim, Person person) {
849	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
850	                .map(Rate::getPct)
851	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, roundingOf(claim)))
852	                .orElse(null);
853	    }
854	
855	    /** How the claim's live figures round: by the sheet's policy date against its date, or for a
856	     *  correction the date of the claim it corrects. */
857	    private RoundingMode roundingOf(Claim claim) {
858	        LocalDate on = claim.getCorrects() == null ? claim.getDate()
859	                : claims.findFirstBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
860	                        .map(Claim::getDate).orElse(claim.getDate());
861	        return Rounding.of(sheets.find(claim.getSheetId())).on(on);
862	    }
