864	    private void record(String event, String user, Person person, Claim claim) {
865	        record(event, user, person, claim, claim.getNumber());
866	    }
867	
868	    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
869	    private void record(String event, String user, Person person, Claim claim, String number) {
870	        record(event, user, person, claim, number, "");
871	    }
872	
873	    private void record(String event, String user, Person person, Claim claim, String number, String extra) {
874	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
875	                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
876	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
877	    }
878	
879	    /** Notify each user watching the person that one of their claims was settled, in the order
880	     *  they started watching. */
881	    private void notifyWatchers(String user, Person person, String number) {
882	        for (PersonWatch w : watches.findByPersonIdOrderByIdAsc(person.getId())) {
883	            audit.recordOnCommit("NOTIFY sheet=" + person.getSheetId() + " by=" + user + " user=" + w.getUserName()
884	                    + " person=" + person.getName() + " number=" + number);
